import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M8 0c2.318 0 2 3 1 5v2l7 2v1H9v2.066L13 13v1H8.964l-.057 1H10v1H6v-1h1.093l-.057-1H3v-1l4-.934V10H0V9l7-2V5C6 3 5.683 0 8 0"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M10 0c2.897 0 2 4 1 6v3l9 2.25V12h-9v4l5 1v1h-5.065l-.041 1H12v1H8v-1h1.106l-.042-1H4v-1l5-1v-4H0v-.75L9 9V6c-1-2-1.897-6 1-6"] as readonly string[];

export const DroneUavIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="drone-uav" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
DroneUavIcon.displayName = `Blueprint6.Icon.DroneUavIcon`;

/**
 * @deprecated Use {@link DroneUavIcon} instead.
 */
export const DroneUav: typeof DroneUavIcon = DroneUavIcon;

export default DroneUavIcon;
